                        : loop ? RegisterOp.BrIfI64GeSLoop : RegisterOp.BrIfI64GeS;
                case RegisterOp.I64GeSImm:
                    return negate
                        ? loop ? RegisterOp.BrIfI64LtSImmLoop : RegisterOp.BrIfI64LtSImm
                        : loop ? RegisterOp.BrIfI64GeSImmLoop : RegisterOp.BrIfI64GeSImm;
                case RegisterOp.I64GeU:
                    return negate
                        ? loop ? RegisterOp.BrIfI64LtULoop : RegisterOp.BrIfI64LtU
                        : loop ? RegisterOp.BrIfI64GeULoop : RegisterOp.BrIfI64GeU;
                case RegisterOp.I64GeUImm:
                    return negate
                        ? loop ? RegisterOp.BrIfI64LtUImmLoop : RegisterOp.BrIfI64LtUImm
                        : loop ? RegisterOp.BrIfI64GeUImmLoop : RegisterOp.BrIfI64GeUImm;
                default: return RegisterOp.Nop;
            }
        }

        /// <summary>
        ///     Gets whether the operation only writes a result to the slot A.
        /// </summary>
        public static bool WritesResult(RegisterOp op)
        {
            switch (op)
            {
                case RegisterOp.Nop:
                case RegisterOp.Return:
                case RegisterOp.Call:
                case RegisterOp.CallIndirect:
                case RegisterOp.BrTable:
                case RegisterOp.GlobalSet:
                case RegisterOp.Fallback:
                case RegisterOp.SelectLocal:
                case RegisterOp.BrIfI32Eq:
                case RegisterOp.BrIfI32EqImm:
                case RegisterOp.BrIfI32EqLoop:
                case RegisterOp.BrIfI32EqImmLoop:
                case RegisterOp.BrIfI32Ne:
                case RegisterOp.BrIfI32NeImm:
                case RegisterOp.BrIfI32NeLoop:
                case RegisterOp.BrIfI32NeImmLoop:
                case RegisterOp.BrIfI32LtS:
                case RegisterOp.BrIfI32LtSImm:
                case RegisterOp.BrIfI32LtSLoop:
                case RegisterOp.BrIfI32LtSImmLoop:
                case RegisterOp.BrIfI32LtU:
                case RegisterOp.BrIfI32LtUImm:
                case RegisterOp.BrIfI32LtULoop:
                case RegisterOp.BrIfI32LtUImmLoop:
                case RegisterOp.BrIfI32GtS:
                case RegisterOp.BrIfI32GtSImm:
                case RegisterOp.BrIfI32GtSLoop:
                case RegisterOp.BrIfI32GtSImmLoop:
                case RegisterOp.BrIfI32GtU:
                case RegisterOp.BrIfI32GtUImm:
                case RegisterOp.BrIfI32GtULoop:
                case RegisterOp.BrIfI32GtUImmLoop:
                case RegisterOp.BrIfI32LeS:
                case RegisterOp.BrIfI32LeSImm:
                case RegisterOp.BrIfI32LeSLoop:
                case RegisterOp.BrIfI32LeSImmLoop:
                case RegisterOp.BrIfI32LeU:
                case RegisterOp.BrIfI32LeUImm:
                case RegisterOp.BrIfI32LeULoop:
                case RegisterOp.BrIfI32LeUImmLoop:
                case RegisterOp.BrIfI32GeS:
                case RegisterOp.BrIfI32GeSImm:
                case RegisterOp.BrIfI32GeSLoop:
                case RegisterOp.BrIfI32GeSImmLoop:
                case RegisterOp.BrIfI32GeU:
                case RegisterOp.BrIfI32GeUImm:
                case RegisterOp.BrIfI32GeULoop:
                case RegisterOp.BrIfI32GeUImmLoop:
                case RegisterOp.BrIfI64Eq:
                case RegisterOp.BrIfI64EqImm:
                case RegisterOp.BrIfI64EqLoop:
                case RegisterOp.BrIfI64EqImmLoop:
                case RegisterOp.BrIfI64Ne:
                case RegisterOp.BrIfI64NeImm:
                case RegisterOp.BrIfI64NeLoop:
                case RegisterOp.BrIfI64NeImmLoop:
                case RegisterOp.BrIfI64LtS:
                case RegisterOp.BrIfI64LtSImm:
                case RegisterOp.BrIfI64LtSLoop:
                case RegisterOp.BrIfI64LtSImmLoop:
                case RegisterOp.BrIfI64LtU:
                case RegisterOp.BrIfI64LtUImm:
                case RegisterOp.BrIfI64LtULoop:
                case RegisterOp.BrIfI64LtUImmLoop:
                case RegisterOp.BrIfI64GtS:
                case RegisterOp.BrIfI64GtSImm:
                case RegisterOp.BrIfI64GtSLoop:
                case RegisterOp.BrIfI64GtSImmLoop:
                case RegisterOp.BrIfI64GtU:
                case RegisterOp.BrIfI64GtUImm:
                case RegisterOp.BrIfI64GtULoop:
                case RegisterOp.BrIfI64GtUImmLoop:
                case RegisterOp.BrIfI64LeS:
                case RegisterOp.BrIfI64LeSImm:
                case RegisterOp.BrIfI64LeSLoop:
                case RegisterOp.BrIfI64LeSImmLoop:
                case RegisterOp.BrIfI64LeU:
                case RegisterOp.BrIfI64LeUImm:
                case RegisterOp.BrIfI64LeULoop:
                case RegisterOp.BrIfI64LeUImmLoop:
                case RegisterOp.BrIfI64GeS:
                case RegisterOp.BrIfI64GeSImm:
                case RegisterOp.BrIfI64GeSLoop:
                case RegisterOp.BrIfI64GeSImmLoop:
                case RegisterOp.BrIfI64GeU:
                case RegisterOp.BrIfI64GeUImm:
                case RegisterOp.BrIfI64GeULoop:
                case RegisterOp.BrIfI64GeUImmLoop:
                case RegisterOp.Store8:
                case RegisterOp.Store16:
                case RegisterOp.Store32:
                case RegisterOp.Store64:
                case RegisterOp.Jump:
                case RegisterOp.JumpLoop:
                case RegisterOp.BrIf:
                case RegisterOp.BrIfLoop:
                case RegisterOp.BrIfZero:
                case RegisterOp.BrIfZeroLoop:
                    return false;
                default:
                    return true;
            }
        }
    }
}
